function bubbleColor(t: number): string {
  // light-sky (#bae6fd) → deep-blue (#1d4ed8)
  const r = Math.round(186 - t * (186 - 29));
  const g = Math.round(230 - t * (230 - 78));
  const b = Math.round(253 - t * (253 - 216));

